package com.mooncast.host;
public final class ScreenDimStateTest {
 public static void main(String[] args){ScreenDimState s=new ScreenDimState();check(!s.active());int first=s.request(0);check(s.active()&&!s.activate(first,50000));s.beginWake();check(!s.noticeReady(first,10)&&!s.activate(first,50000));s.bright();check(!s.active());int second=s.request(0);check(s.noticeReady(second,100));check(!s.noticeReady(second,200));check(!s.activate(second,3099));check(s.activate(second,3100)&&s.dimmedAt==3100);check(s.phase==ScreenDimState.Phase.DIMMED);s.beginWake();check(!s.activate(second,9000));s.bright();int old=s.request(0);int fresh=s.request(0);check(!s.noticeReady(old,10)&&!s.activate(old,50000));check(s.noticeReady(fresh,200)&&!s.activate(fresh,3199)&&s.activate(fresh,3200));s.bright();check(!s.active());int expired=s.request(0);check(s.noticeExpired(expired,10000)&&!s.noticeReady(expired,10000)&&!s.activate(expired,50000));s.bright();int timeout=s.request(0);s.bright();check(!s.noticeReady(timeout,100)&&!s.activate(timeout,50000));System.out.println("PASS window dimming state: first-frame gate, unchanged 3s countdown, duplicate/late callbacks, cancellation and full waking gesture; no physical-brightness claim");}
 static void check(boolean b){if(!b)throw new AssertionError();}
}
